mapper.select:
SELECT col.id,col.contract_id,col.total,col.amount,col.debt,col.is_end,col.is_notice, col.last_pay_date,col.create_time,col.service_class_id,col.remark,( CASE WHEN col.debt = 0 THEN '正常' ELSE ( CASE WHEN ctr.pay_type = 1 THEN ( CASE WHEN DATEDIFF( ctr.contract_start_date, NOW( ) ) <= 7 AND DATEDIFF( ctr.contract_start_date, NOW( ) ) > 0 THEN '即将到期' WHEN ctr.contract_start_date < NOW( ) THEN '已经欠费' ELSE '正常' END ) ELSE ( CASE WHEN DATEDIFF( col.last_pay_date, NOW( ) ) <= 7 AND DATEDIFF( col.last_pay_date, NOW( ) ) > 0 THEN '即将到期' WHEN col.last_pay_date < NOW( ) THEN '已经欠费' ELSE '正常' END ) END ) END ) is_warning, (SELECT user_name from sys_user where user_id = cus.bookkeeping_accounting_user_id) bookkeepingAccounting, ctr.pay_type,cus.customer_name,ctr.contract_no,ctr.status FROM `t_collection` col LEFT JOIN t_contract ctr on col.contract_id = ctr.contract_id LEFT JOIN t_customer cus on cus.id = ctr.customer_id where 1 = 1
AND col.is_warning = #{isWarning}
AND YEAR(col.last_pay_date) = #{year} and MONTH(col.last_pay_date) = #{month}
AND col.service_class_id = #{serviceClassId}
AND col.dept_id = #{deptId}
AND cus.customer_name LIKE CONCAT('%',#{customerName},'%')
AND col.is_end = #{isEnd}
AND col.is_del = #{isDel}
AND ctr.contract_no like concat('%', #{contractNo}, '%')
ORDER BY col.id DESC
